{"task": "Find log messages containing ISO-8601 timestamps in YYYY-MM-DD format", "sql": "SELECT * FROM logs WHERE regexp_like(message, '20[0-9]{2}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])')"}
{"task": "Count error level logs with ISO-8601 timestamps from last week", "sql": "SELECT count(*) FROM logs WHERE level = 'ERROR' AND regexp_like(message, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}') AND ts >= current_timestamp - interval '7 days'"}
{"task": "Identify service logs with ISO timestamps in yyyy-MM-dd format", "sql": "SELECT DISTINCT service, message FROM logs WHERE regexp_like(message, '\\d{4}-\\d{2}-\\d{2}') AND service IS NOT NULL"}
{"task": "Find log entries with timestamp patterns including milliseconds", "sql": "SELECT * FROM logs WHERE regexp_like(message, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}')"}
{"task": "Extract events with user paths containing date patterns", "sql": "SELECT * FROM events WHERE regexp_like(path, '20[0-9]{2}/[0-1][0-9]/[0-3][0-9]')"}
{"task": "Count logs where message has ISO timestamp in format yyyy-MM-dd HH:mm:ss", "sql": "SELECT count(*) FROM logs WHERE regexp_like(message, '[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}')"}
{"task": "Find messages with timezone-aware ISO timestamps", "sql": "SELECT message FROM logs WHERE regexp_like(message, '[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\+|-)[0-9]{2}:[0-9]{2}')"}
{"task": "Identify log messages with multiple timestamp formats", "sql": "SELECT message FROM logs WHERE regexp_like(message, '(20[0-9]{2}-[0-9]{2}-[0-9]{2}|[0-9]{4}/[0-9]{2}/[0-9]{2})')"}
{"task": "Find service logs with timestamp patterns in ISO 8601 basic format", "sql": "SELECT * FROM logs WHERE regexp_like(message, '20[0-9]{6}T[0-9]{6}') AND service = 'api-service'"}
{"task": "Count events where path contains date strings without slashes", "sql": "SELECT count(*) FROM events WHERE regexp_like(path, '[0-9]{8}')"}

